package com.ric.pet;
import android.Manifest;import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Build;import android.os.Bundle;import android.provider.Settings;import android.view.Gravity;import android.view.View;import android.widget.*;
public class MainActivity extends Activity{
 private TextView status,sizeLabel,speedLabel,name;private FrameLayout previewBox;private PetView preview;private final String[] labels={"Yuki — white/blue neko maid","Hina — dark/pink neko maid","Tora — orange chibi cat","Momo — black chibi cat"};private final String[] ids={"YUKI","REN","TORA","MOMO"};
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);ScrollView sv=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(30),dp(18),dp(28));root.setGravity(Gravity.CENTER_HORIZONTAL);root.setBackgroundColor(0xfffff7f8);TextView title=text("RIC PET",30,0xff342d3a);title.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);root.addView(title);root.addView(text("v0.6.2 • cute pixel desktop companion",13,0xff8d7180));status=text("",13,0xff574d55);root.addView(status);
  name=text("CHARACTER PREVIEW",16,0xff342d3a);name.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);root.addView(name);previewBox=new FrameLayout(this);previewBox.setLayoutParams(new LinearLayout.LayoutParams(dp(210),dp(210)));GradientDrawable card=new GradientDrawable();card.setColor(0xffffecef);card.setCornerRadius(dp(22));card.setStroke(dp(2),0xffe8a8b7);previewBox.setBackground(card);preview=new PetView(this);previewBox.addView(preview,new FrameLayout.LayoutParams(-1,-1));root.addView(previewBox);
  LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);String[] a={"Idle","Walk","Eat","Drink","Type","Watch","Listen","Sleep"};PetView.State[] st={PetView.State.IDLE,PetView.State.WALK,PetView.State.EAT,PetView.State.DRINK,PetView.State.TYPING,PetView.State.MEDIA_WATCH,PetView.State.MUSIC,PetView.State.SLEEP};for(int i=0;i<a.length;i++){final int n=i;Button x=new Button(this);x.setText(a[i]);x.setAllCaps(false);x.setTextSize(10);x.setOnClickListener(v->preview.setState(st[n]));actions.addView(x,new LinearLayout.LayoutParams(0,dp(44),1));}HorizontalScrollView hs=new HorizontalScrollView(this);hs.addView(actions);root.addView(hs,new LinearLayout.LayoutParams(-1,dp(50)));
  root.addView(text("Pilih karakter",15,0xff342d3a));Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));String cur=PetPreferences.cat(this);for(int i=0;i<ids.length;i++)if(ids[i].equals(cur))sp.setSelection(i);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){PetPreferences.cat(MainActivity.this,ids[pos]);name.setText("CHARACTER PREVIEW • "+labels[pos]);preview.refreshCharacter();}public void onNothingSelected(android.widget.AdapterView<?> p){}});root.addView(sp,new LinearLayout.LayoutParams(-1,dp(55)));
  root.addView(text("Preview di atas memakai renderer sprite yang sama dengan pet floating. Coba langsung Idle, Walk, Eat, Drink, Type, Watch, Listen, dan Sleep sebelum mengaktifkan overlay.",12,0xff8d7180));root.addView(button("Aktifkan / Restart RIC Pet",v->{stopService(new Intent(this,OverlayPetService.class));startPet();}));root.addView(button("Hentikan Pet",v->{stopService(new Intent(this,OverlayPetService.class));refresh();}));root.addView(button("Izin tampil di atas aplikasi",v->requestOverlay()));root.addView(button("Aktifkan reaksi mengetik & scroll",v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))));root.addView(text("Accessibility hanya mendeteksi TEXT_CHANGED dan VIEW_SCROLLED; isi tulisan tidak dibaca/disimpan/dikirim.",11,0xff8d7180));sizeLabel=text("",13,0xff574d55);root.addView(sizeLabel);SeekBar size=new SeekBar(this);size.setMax(224);size.setProgress(PetPreferences.size(this)-96);root.addView(size);size.setOnSeekBarChangeListener(listener(v->{PetPreferences.size(this,v+96);refreshLabels();}));speedLabel=text("",13,0xff574d55);root.addView(speedLabel);SeekBar speed=new SeekBar(this);speed.setMax(150);speed.setProgress(PetPreferences.speed(this)-50);root.addView(speed);speed.setOnSeekBarChangeListener(listener(v->{PetPreferences.speed(this,v+50);refreshLabels();}));CheckBox boot=new CheckBox(this);boot.setText("Jalankan pet otomatis setelah HP restart");boot.setChecked(PetPreferences.autoStart(this));boot.setOnCheckedChangeListener((x,c)->PetPreferences.autoStart(this,c));root.addView(boot);sv.addView(root);setContentView(sv);refresh();refreshLabels();}
 interface V{void go(int v);}private SeekBar.OnSeekBarChangeListener listener(V x){return new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){x.go(p);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}};}interface Click{void go(View v);}private Button button(String s,Click c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(c::go);b.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(50)));return b;}private TextView text(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(6),0,dp(6));return t;}private void requestOverlay(){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}private void startPet(){if(!Settings.canDrawOverlays(this)){requestOverlay();return;}Intent i=new Intent(this,OverlayPetService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);refresh();}private void refresh(){status.setText(Settings.canDrawOverlays(this)?"Overlay • AKTIF":"Overlay • BELUM AKTIF");}private void refreshLabels(){sizeLabel.setText("Ukuran pet: "+PetPreferences.size(this)+" dp");speedLabel.setText("Kecepatan: "+PetPreferences.speed(this)+"%");}@Override protected void onResume(){super.onResume();if(status!=null)refresh();}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}